<h2 class="h4 mb-3"><?= $id ? '编辑' : '新增' ?>优惠码</h2><form method="post" class="card p-3 admin-form"><?= csrf_field() ?><div class="row"><?php foreach ($defs as $k => $f): $v = isset($row[$k]) ? $row[$k] : '';
    $t = isset($f[1]) ? $f[1] : 'text'; ?><div class="col-md-6 mb-3"><label class="form-label"><?= h($f[0]) ?></label><?php if ($t === 'multiselect'):$sel = explode(',', (string)$v); ?><select class="form-select" name="<?= h($k) ?>/a[]" multiple><?php foreach ($f[2] as $ov => $ol): ?><option value="<?= h($ov) ?>" <?= in_array((string)$ov, $sel, true) ? 'selected' : '' ?>><?= h($ol) ?></option><?php endforeach; ?></select><?php elseif ($t === 'switch'): ?><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="<?= h($k) ?>" value="1" <?= $v ? 'checked' : '' ?>></div><?php elseif ($t === 'select'): ?><select class="form-select" name="<?= h($k) ?>"><?php foreach ($f[2] as $ov => $ol): ?><option value="<?= h($ov) ?>" <?= (string)$v === (string)$ov ? 'selected' : '' ?>><?= h($ol) ?></option><?php endforeach; ?></select><?php elseif ($t === 'datetime'): ?><input class="form-control" type="datetime-local" name="<?= h($k) ?>" value="<?= (int)$v > 0 ? date('Y-m-d\TH:i', (int)$v) : '' ?>"><?php else: ?><input class="form-control" name="<?= h($k) ?>" value="<?= h($v) ?>" <?= $k === 'code' ? 'pattern="[A-Z0-9_-]{3,40}"' : '' ?>><?php endif; ?></div><?php endforeach; ?></div><button class="btn btn-primary">保存</button> <a class="btn btn-outline-secondary" href="<?= h(url_to('admin/coupon/index')) ?>">返回</a></form>